import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 4

    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    )

    parsed_rows = []
    for row in reader:
        if len(row) > expected_width:
            row = row[: expected_width - 1] + [",".join(row[expected_width - 1 :])]
        elif len(row) < expected_width:
            row = row + [""] * (expected_width - len(row))
        parsed_rows.append(row)

    def is_number(value):
        value = value.strip()
        return bool(
            re.fullmatch(
                r"[+-]?(?:(?:\d+(?:\.\d*)?)|(?:\.\d+))(?:[eE][+-]?\d+)?",
                value,
            )
        )

    nonempty_indices = [
        index for index, row in enumerate(parsed_rows) if any(value.strip() for value in row)
    ]

    has_header = False
    if len(nonempty_indices) >= 2:
        first_index = nonempty_indices[0]
        first_row = parsed_rows[first_index]
        following_rows = [parsed_rows[index] for index in nonempty_indices[1:11]]

        numeric_positions = []
        for column_index in range(expected_width):
            values = [row[column_index] for row in following_rows if row[column_index].strip()]
            if values and sum(is_number(value) for value in values) > len(values) / 2:
                numeric_positions.append(column_index)

        if numeric_positions:
            nonnumeric_header_positions = sum(
                bool(first_row[column_index].strip())
                and not is_number(first_row[column_index])
                for column_index in numeric_positions
            )
            has_header = nonnumeric_header_positions > len(numeric_positions) / 2

    if has_header:
        header_index = nonempty_indices[0]
        columns = parsed_rows[header_index]
        rows = parsed_rows[:header_index] + parsed_rows[header_index + 1 :]
    else:
        columns = [f"column_{index + 1}" for index in range(expected_width)]
        rows = parsed_rows

    return {"columns": columns, "rows": rows}
